#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [KinematicViscosity; 9] = [
        KinematicViscosity::const_new(1234.5, KinematicViscosityUnit::SquareMeterPerSecond),
        KinematicViscosity::const_new(1234.5, KinematicViscosityUnit::Stokes),
        KinematicViscosity::const_new(1234.5, KinematicViscosityUnit::Nanostokes),
        KinematicViscosity::const_new(1234.5, KinematicViscosityUnit::Microstokes),
        KinematicViscosity::const_new(1234.5, KinematicViscosityUnit::Millistokes),
        KinematicViscosity::const_new(1234.5, KinematicViscosityUnit::Centistokes),
        KinematicViscosity::const_new(1234.5, KinematicViscosityUnit::Decistokes),
        KinematicViscosity::const_new(1234.5, KinematicViscosityUnit::Kilostokes),
        KinematicViscosity::const_new(1234.5, KinematicViscosityUnit::SquareFootPerSecond),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(KinematicViscosityUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            KinematicViscosity::new(1234.5_f64, unit)
                .as_base()
                .to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in KinematicViscosityUnit::ALL {
            assert_eq!(
                KinematicViscosity::const_new(v, unit).as_base().to_bits(),
                KinematicViscosity::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = KinematicViscosity::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            KinematicViscosity::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in KinematicViscosityUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        KinematicViscosity::from_base(0.0).auto_unit().unit,
        KinematicViscosityUnit::SquareMeterPerSecond
    );
}

